    public static function key(string$s):string{return 'tax_filing_local_'.substr(hash('sha256',$s),0,24);}
    public static function messages(string$locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$s=>$v)$out[self::key($s)]=$en?$v:$s;return$out;}
    public static function text(string$s,array$messages,array$values=[]):string
    {
        if(isset($messages[self::key($s)]))$text=$messages[self::key($s)];elseif(str_contains($s,': ')){[$label,$detail]=explode(': ',$s,2);$text=self::text($label,$messages).': '.self::text($detail,$messages);}else{$text=TaxAutoDraftMessages::text($s,$messages);if($text===$s)$text=FinanceTaxMessages::text($s,$messages);}if(str_ends_with($s,' – Noch zu klären.'))$text=self::text(substr($s,0,-strlen(' – Noch zu klären.')),$messages).' – '.self::text('Noch zu klären.',$messages);foreach($values as$key=>$value)if(is_scalar($value))$text=str_replace('{'.$key.'}',(string)$value,$text);return$text;
    }
